"""Export coherent coastal Nishita radiance with verified panorama directions.
Sky excludes the sun; a narrow solar probe integrates the full-minus-sky disk.
Only source radiance is exported. No display transform or final-scene renderer.
"""
from pathlib import Path
import bpy,math,json,sys
import numpy as np
from mathutils import Vector
out=Path(sys.argv[sys.argv.index('--')+1]).resolve();out.mkdir(parents=True,exist_ok=True)
assert bpy.app.version[:2]==(4,3),bpy.app.version_string
bpy.ops.wm.read_factory_settings(use_empty=True);scene=bpy.context.scene;scene.render.engine='CYCLES';scene.cycles.device='CPU';scene.cycles.samples=1;scene.cycles.use_denoising=False;scene.cycles.use_adaptive_sampling=False;scene.cycles.max_bounces=1;scene.render.threads_mode='FIXED';scene.render.threads=2;scene.render.image_settings.file_format='OPEN_EXR';scene.render.image_settings.color_depth='32';scene.render.image_settings.color_mode='RGB';scene.view_settings.view_transform='Raw';scene.view_settings.look='None';scene.view_settings.exposure=0;scene.view_settings.gamma=1;scene.render.film_transparent=False;scene.cycles.pixel_filter_type='BOX';scene.cycles.filter_width=.01
world=bpy.data.worlds.new('Coastal coherent source');world.use_nodes=True;scene.world=world;nodes=world.node_tree.nodes;nodes.clear();links=world.node_tree.links;sk=nodes.new('ShaderNodeTexSky');sk.sky_type='NISHITA';sk.sun_intensity=1;sk.sun_size=math.radians(.532);sun=np.array([-.42,-.47,.776]);sun/=np.linalg.norm(sun);sk.sun_elevation=math.asin(sun[2]);sk.sun_rotation=(math.pi/2-math.atan2(sun[1],sun[0]))%(2*math.pi);sk.altitude=10.;sk.air_density=1.;sk.dust_density=.8;sk.ozone_density=1.;bg=nodes.new('ShaderNodeBackground');bg.inputs['Strength'].default_value=1;output=nodes.new('ShaderNodeOutputWorld');links.new(sk.outputs['Color'],bg.inputs['Color']);links.new(bg.outputs[0],output.inputs[0]);camdata=bpy.data.cameras.new('radiance camera');camera=bpy.data.objects.new('radiance camera',camdata);scene.collection.objects.link(camera);scene.camera=camera

def render(name,width,height,samples=1):
 scene.render.resolution_x=width;scene.render.resolution_y=height;scene.render.resolution_percentage=100;scene.cycles.samples=samples;scene.render.filepath=str(out/(name+'.exr'));bpy.ops.render.render(write_still=True);im=bpy.data.images.load(scene.render.filepath,check_existing=False);values=np.flipud(np.asarray(im.pixels[:],np.float32).reshape(height,width,4)[:,:,:3]).copy();assert np.isfinite(values).all() and values.min()>=0;(np.save(out/(name+'.npy'),values));bpy.data.images.remove(im);print('PROBE',name,float(values.min()),float(values.max()),flush=True);return values
# Read the actual directions from a diagnostic world shader, not a guessed camera convention.
g=nodes.new('ShaderNodeNewGeometry');mapping=nodes.new('ShaderNodeVectorMath');mapping.operation='MULTIPLY_ADD';mapping.inputs[1].default_value=(.5,.5,.5);mapping.inputs[2].default_value=(.5,.5,.5);links.new(g.outputs['Incoming'],mapping.inputs[0]);links.new(mapping.outputs['Vector'],bg.inputs['Color']);camdata.type='PERSP';camera.rotation_euler=Vector((1,0,0)).to_track_quat('-Z','Y').to_euler();camdata.lens=2000
control=render('direction_sign_control',5,5);center=control[2,2]*2-1;sign=1 if center[0]>0 else -1;assert abs(abs(center[0])-1)<1e-5 and np.linalg.norm(center[1:])<1e-3
camdata.type='PANO';camdata.panorama_type='EQUIRECTANGULAR';camera.rotation_euler=(0,0,0);directions=(render('panorama_directions',1024,512)*2-1)*sign;assert np.max(abs(np.linalg.norm(directions,axis=2)-1))<2e-5;np.save(out/'panorama_world_directions.npy',directions)
links.new(sk.outputs['Color'],bg.inputs['Color']);sk.sun_disc=False;render('panorama_sky_without_solar_disc',1024,512)
# Perspective pixel solid-angle Jacobian is integrated over a0.7degree square.
# Same directions/sample seed on both passes; solar limb and edge are resolved.
camdata.type='PERSP';camera.rotation_euler=Vector(sun).to_track_quat('-Z','Y').to_euler();camdata.sensor_fit='HORIZONTAL';camdata.sensor_width=36;fov=math.radians(.7);camdata.lens=36/(2*math.tan(fov/2));N=256;sk.sun_disc=False;off=render('solar_patch_sky_only',N,N,16);sk.sun_disc=True;on=render('solar_patch_full_model',N,N,16);residual=on-off;assert residual.min()>-1e-4 and residual.max()>100
xy=((np.arange(N)+.5)/N*2-1)*math.tan(fov/2);r2=xy[:,None]**2+xy[None,:]**2;dA=(2*math.tan(fov/2)/N)**2;irradiance=np.sum(residual*(dA/(1+r2)**2)[...,None],axis=(0,1));outside=r2>math.tan(math.radians(.266)+math.radians(.005))**2;assert np.max(abs(residual[outside]))<.002
record={'generator':'Blender '+bpy.app.version_string+' Cycles Nishita shader radiance','sun_direction':sun.tolist(),'sun_diameter_deg':.532,'altitude_m':10,'air_density':1.,'dust_density':.8,'ozone_density':1.,'sun_intensity':1.,'solar_residual_irradiance_linear_rgb':irradiance.tolist(),'solar_probe_samples_per_pixel':16,'solar_probe_resolution':[N,N],'solar_probe_fov_deg':.7,'panorama_resolution':[1024,512],'one_solar_source':True,'sky_disc_enabled_in_export':False,'color_space':'scene-linear Rec.709/sRGB primaries before view transform','normalization':'No source scaling applied at this export stage','direction_probe_sign':sign,'source_url':'https://github.com/blender/blender/blob/v4.3.2/intern/cycles/kernel/svm/sky.h','limitations':['Authored coastal clear daylight settings, not measured weather/time.','Native renderer uses a uniform disk matched to model residual irradiance; solar limb darkening is not retained.','RGB export must be colorimetrically fitted to native LIGHT spectral controls; it is not an original spectral radiance export.','Panoramic source is directionally resampled to native Y-pole texture coordinates.']}
(out/'NISHITA_EXPORT.json').write_text(json.dumps(record,indent=2)+'\n');print('COMPLETED',json.dumps(record),flush=True)
